class Solution {
public:
    int findDerangement(int n) {
        const int MOD = 1e9 + 7;
        if (n == 1) return 0;
        if (n == 2) return 1;
        long long prev2 = 0, prev1 = 1;
        for (int i = 3; i <= n; i++) {
            long long curr = (i - 1) * (prev1 + prev2) % MOD;
            prev2 = prev1;
            prev1 = curr;
        }
        return (int)prev1;
    }
};

class Solution {
    public int findDerangement(int n) {
        final int MOD = 1000000007;
        if (n == 1) return 0;
        if (n == 2) return 1;
        long prev2 = 0, prev1 = 1;
        for (int i = 3; i <= n; i++) {
            long curr = ((long) (i - 1) * (prev1 + prev2)) % MOD;
            prev2 = prev1;
            prev1 = curr;
        }
        return (int) prev1;
    }
}

var findDerangement = function(n) {
    const MOD = 1000000007n;
    if (n === 1) return 0;
    if (n === 2) return 1;
    let prev2 = 0n, prev1 = 1n;
    for (let i = 3n; i <= BigInt(n); i++) {
        const curr = ((i - 1n) * (prev1 + prev2)) % MOD;
        prev2 = prev1;
        prev1 = curr;
    }
    return Number(prev1);
};
